//! Bessel, Lambert W, hypergeometric and Owen's T functions against high-precision reference values
//! (`fixtures/special_extra.json`, generated by `fixtures/special_extra.py` with mpmath), plus recurrences,
//! identities, special values and derivatives against finite differences.

use keanu_tensor::special::*;
use serde_json::Value;
use std::f64::consts::{E, PI};

fn evaluate(name: &str, x: &[f64]) -> f64 {
    let derivative = |a: f64, b: f64, c: f64, z: f64, i: usize, j: Option<usize>| {
        let d = hyp2f1_derivatives(a, b, c, z);
        match j {
            None => d.gradient[i],
            Some(j) => d.hessian[i][j],
        }
    };
    match (name, x) {
        ("log_bessel_k", &[nu, x]) => log_bessel_k(nu, x),
        ("bessel_k", &[nu, x]) => bessel_k(nu, x),
        ("bessel_k_scaled", &[nu, x]) => bessel_k_scaled(nu, x),
        ("bessel_k_ratio", &[nu, x]) => bessel_k_ratio(nu, x),
        ("log_bessel_k_dx", &[nu, x]) => log_bessel_k_dx(nu, x),
        ("log_bessel_i", &[nu, x]) => log_bessel_i(nu, x),
        ("bessel_i", &[nu, x]) => bessel_i(nu, x),
        ("bessel_i_scaled", &[nu, x]) => bessel_i_scaled(nu, x),
        ("bessel_i_ratio", &[nu, x]) => bessel_i_ratio(nu, x),
        ("log_bessel_i_dx", &[nu, x]) => log_bessel_i_dx(nu, x),
        ("lambert_w0", &[x]) => lambert_w0(x),
        ("lambert_wm1", &[x]) => lambert_wm1(x),
        ("owens_t", &[h, a]) => owens_t(h, a),
        ("hyp2f1", &[a, b, c, z]) => hyp2f1(a, b, c, z),
        ("hyp2f1_dz", &[a, b, c, z]) => hyp2f1_dz(a, b, c, z),
        ("hyp2f1_da", &[a, b, c, z]) => derivative(a, b, c, z, 0, None),
        ("hyp2f1_db", &[a, b, c, z]) => derivative(a, b, c, z, 1, None),
        ("hyp2f1_dc", &[a, b, c, z]) => derivative(a, b, c, z, 2, None),
        ("hyp2f1_dz2", &[a, b, c, z]) => derivative(a, b, c, z, 3, Some(3)),
        ("hyp2f1_da2", &[a, b, c, z]) => derivative(a, b, c, z, 0, Some(0)),
        ("hyp2f1_dadz", &[a, b, c, z]) => derivative(a, b, c, z, 0, Some(3)),
        ("hyp2f1_dbdc", &[a, b, c, z]) => derivative(a, b, c, z, 1, Some(2)),
        _ => panic!("unknown fixture function {name} with {} arguments", x.len()),
    }
}

#[test]
fn every_function_matches_the_high_precision_fixture() {
    let text = include_str!("fixtures/special_extra.json");
    let fixture: Value = serde_json::from_str(text).unwrap();
    let cases = fixture["cases"].as_array().unwrap();
    assert!(cases.len() > 2000);
    let mut failures = Vec::new();
    for case in cases {
        let name = case["f"].as_str().unwrap();
        let args: Vec<f64> = case["x"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_f64().unwrap())
            .collect();
        let expected = case["v"].as_f64().unwrap();
        let tol = case["tol"].as_f64().unwrap();
        let floor = case["floor"].as_f64().unwrap();
        let actual = evaluate(name, &args);
        let error = (actual - expected).abs() / expected.abs().max(floor);
        if error.is_nan() || error > tol {
            failures.push(format!(
                "{name}{args:?} = {actual:e}, expected {expected:e} (error {error:.1e} > {tol:e})"
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} failures:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

fn close(actual: f64, expected: f64, tol: f64) -> bool {
    (actual - expected).abs() <= tol * expected.abs().max(1e-300)
}

/// The central difference of f at x with step h.
fn central(f: impl Fn(f64) -> f64, x: f64, h: f64) -> f64 {
    (f(x + h) - f(x - h)) / (2.0 * h)
}

const ORDERS: [f64; 12] = [
    0.0, 0.3, 0.5, 1.0, 1.7, 2.5, 4.0, 9.5, 29.5, 30.0, 45.0, 200.0,
];
const ARGUMENTS: [f64; 11] = [
    1e-4, 0.05, 0.7, 1.99, 2.01, 4.0, 15.0, 29.9, 30.1, 120.0, 2500.0,
];

#[test]
fn bessel_k_satisfies_its_recurrence_and_half_integer_closed_forms() {
    for nu in ORDERS {
        for x in ARGUMENTS {
            // K_{ν+1} = K_{ν−1} + (2ν/x) K_ν, in ratios: K_{ν+1}/K_ν = K_{ν−1}/K_ν + 2ν/x (all positive)
            let up = bessel_k_ratio(nu, x);
            let below = (log_bessel_k(nu - 1.0, x) - log_bessel_k(nu, x)).exp();
            assert!(
                close(up, below + 2.0 * nu / x, 1e-12),
                "ν = {nu}, x = {x}: {up} vs {}",
                below + 2.0 * nu / x
            );
            // the ratio agrees with the logs
            let from_logs = (log_bessel_k(nu + 1.0, x) - log_bessel_k(nu, x)).exp();
            assert!(close(up, from_logs, 1e-12), "ν = {nu}, x = {x}");
        }
    }
    for x in [1e-3, 0.5, 3.0, 40.0, 600.0] {
        let half = (PI / (2.0 * x)).sqrt() * (-x).exp();
        assert!(close(bessel_k(0.5, x), half, 1e-14), "{x}");
        assert!(close(bessel_k(-0.5, x), half, 1e-14), "{x}");
        assert!(
            close(bessel_k(1.5, x), half * (1.0 + 1.0 / x), 1e-14),
            "{x}"
        );
        assert!(close(
            bessel_k_scaled(0.5, x),
            (PI / (2.0 * x)).sqrt(),
            1e-14
        ));
    }
}

#[test]
fn bessel_i_and_k_satisfy_the_wronskian_and_i_matches_the_integer_orders() {
    for nu in ORDERS {
        for x in ARGUMENTS {
            // I_ν K_{ν+1} + I_{ν+1} K_ν = 1/x, as x I_ν K_ν (K_{ν+1}/K_ν + I_{ν+1}/I_ν) = 1
            let product = (x.ln() + log_bessel_i(nu, x) + log_bessel_k(nu, x)).exp();
            let w = product * (bessel_k_ratio(nu, x) + bessel_i_ratio(nu, x));
            // the logs of I and K, each with a rounding error of about 1e-16 of its size, nearly cancel
            let tol = 1e-14 + 4e-16 * (log_bessel_i(nu, x).abs() + log_bessel_k(nu, x).abs());
            assert!(close(w, 1.0, tol), "ν = {nu}, x = {x}: {w}");
            // the I ratio agrees with the logs
            let from_logs = (log_bessel_i(nu + 1.0, x) - log_bessel_i(nu, x)).exp();
            assert!(
                close(bessel_i_ratio(nu, x), from_logs, 1e-12),
                "ν = {nu}, x = {x}"
            );
        }
    }
    for x in [0.0, 1e-5, 0.5, 7.0, 29.0, 31.0, 300.0, 1e5] {
        let logs_agree = |a: f64, b: f64| (a - b).abs() <= 1e-14 * b.abs().max(1.0);
        assert!(logs_agree(log_bessel_i(0.0, x), log_bessel_i0(x)), "{x}");
        if x > 0.0 {
            assert!(logs_agree(log_bessel_i(1.0, x), log_bessel_i1(x)), "{x}");
            let sinh = (2.0 / (PI * x)).sqrt() * x.sinh();
            if x < 700.0 {
                assert!(close(bessel_i(0.5, x), sinh, 1e-14), "{x}");
            }
        }
    }
}

#[test]
fn bessel_functions_are_continuous_across_their_method_switches() {
    for (nu, x) in [
        (29.999_999_999, 5.0),
        (29.999_999_999, 100.0),
        (29.999_999_999, 0.01),
    ] {
        // order switch to the Debye expansion
        let (a, b) = (log_bessel_k(nu, x), log_bessel_k(30.0, x));
        assert!((a - b).abs() < 1e-7 * a.abs().max(1.0), "{a} {b}");
        let (a, b) = (log_bessel_i(nu, x), log_bessel_i(30.0, x));
        assert!((a - b).abs() < 1e-7 * a.abs().max(1.0), "{a} {b}");
    }
    let next = |x: f64| f64::from_bits(x.to_bits() + 1);
    for nu in [0.0, 0.4, 3.0, 7.0] {
        for x in [2.0, 30.0, 49.0] {
            for (a, b) in [
                (log_bessel_k(nu, x), log_bessel_k(nu, next(x))),
                (log_bessel_i(nu, x), log_bessel_i(nu, next(x))),
                (bessel_i_ratio(nu, x), bessel_i_ratio(nu, next(x))),
                (bessel_k_ratio(nu, x), bessel_k_ratio(nu, next(x))),
            ] {
                assert!(close(a, b, 1e-13), "ν = {nu}, x = {x}: {a} {b}");
            }
        }
    }
}

#[test]
fn bessel_derivatives_match_finite_differences() {
    for nu in ORDERS {
        for x in [0.05, 0.7, 2.5, 15.0, 31.0, 120.0] {
            let h = 1e-5 * x;
            let fd = central(|x| log_bessel_k(nu, x), x, h);
            assert!(close(log_bessel_k_dx(nu, x), fd, 1e-7), "ν = {nu}, x = {x}");
            let fd = central(|x| log_bessel_i(nu, x), x, h);
            assert!(close(log_bessel_i_dx(nu, x), fd, 1e-7), "ν = {nu}, x = {x}");
            if x < 100.0 && nu < 50.0 {
                let fd = central(|x| bessel_k(nu, x), x, h);
                assert!(close(bessel_k_dx(nu, x), fd, 1e-7), "ν = {nu}, x = {x}");
            }
        }
    }
}

#[test]
fn bessel_functions_handle_the_ends_of_their_domains() {
    assert_eq!(log_bessel_k(1.0, 0.0), f64::INFINITY);
    assert_eq!(bessel_k(0.0, 0.0), f64::INFINITY);
    assert_eq!(log_bessel_k(1.0, f64::INFINITY), f64::NEG_INFINITY);
    assert_eq!(bessel_k(2.0, 1e4), 0.0);
    assert!(bessel_k_scaled(2.0, 1e4) > 0.0);
    assert!(log_bessel_k(1.0, -1.0).is_nan());
    assert!(log_bessel_k(f64::NAN, 1.0).is_nan());
    assert!(log_bessel_k(f64::INFINITY, 1.0).is_nan());
    assert_eq!(log_bessel_k(-2.5, 3.0), log_bessel_k(2.5, 3.0));
    assert_eq!(log_bessel_i(0.0, 0.0), 0.0);
    assert_eq!(log_bessel_i(0.5, 0.0), f64::NEG_INFINITY);
    assert_eq!(log_bessel_i(0.5, f64::INFINITY), f64::INFINITY);
    assert!(log_bessel_i(-0.5, 1.0).is_nan());
    assert!(log_bessel_i(1.0, -1.0).is_nan());
    assert_eq!(bessel_i_ratio(2.0, 0.0), 0.0);
    assert_eq!(bessel_i_ratio(2.0, f64::INFINITY), 1.0);
    assert_eq!(bessel_k_ratio(2.0, f64::INFINITY), 1.0);
    assert_eq!(log_bessel_i_dx(0.0, 0.0), 0.0);
    assert_eq!(log_bessel_i_dx(1.0, 0.0), f64::INFINITY);
    assert_eq!(log_bessel_k_dx(1.0, 0.0), f64::NEG_INFINITY);
    // huge orders and arguments stay finite in logs
    assert!(log_bessel_k(1e5, 1e-200).is_finite());
    assert!(log_bessel_i(1e5, 1e-200).is_finite());
    assert!(log_bessel_i(3.0, 1e300).is_finite());
}

#[test]
fn lambert_w_inverts_w_exp_w() {
    for x in [
        -0.367_879, -0.36, -0.3, -0.2, -1e-3, -1e-200, 1e-200, 1e-3, 0.5, 1.0, 5.0, 1e3, 1e200,
    ] {
        let w = lambert_w0(x);
        assert!(w >= -1.0);
        // w eʷ = x, as ln w + w = ln x away from 0
        let logs_agree = |w: f64, x: f64| {
            let (lhs, rhs) = (w.abs().ln() + w, x.abs().ln());
            (lhs - rhs).abs() <= 1e-14 * rhs.abs().max(1.0)
        };
        if x.abs() > 1e-100 && w.abs() > 1e-3 {
            assert!(logs_agree(w, x), "{x}");
        } else {
            assert!(close(w * w.exp(), x, 1e-14), "{x}");
        }
        if x < 0.0 {
            let w = lambert_wm1(x);
            assert!(w <= -1.0);
            assert!(logs_agree(w, x), "{x}");
        }
    }
    assert_eq!(lambert_w0(-1.0 / E), -1.0);
    assert_eq!(lambert_wm1(-1.0 / E), -1.0);
    assert!(close(lambert_w0(E), 1.0, 1e-15));
    assert_eq!(lambert_w0(0.0), 0.0);
    assert_eq!(lambert_w0(f64::INFINITY), f64::INFINITY);
    assert_eq!(lambert_wm1(0.0), f64::NEG_INFINITY);
    assert!(lambert_w0(-0.4).is_nan());
    assert!(lambert_wm1(-0.4).is_nan());
    assert!(lambert_wm1(0.1).is_nan());
    assert!(lambert_w0(f64::NAN).is_nan());
    // monotone on each branch, including through the switch from the branch-point series
    let mut previous = -1.0;
    for i in 1..2000 {
        let x = -1.0 / E + f64::from(i) * 1e-5;
        let w = lambert_w0(x);
        assert!(w > previous, "{x}");
        previous = w;
    }
}

#[test]
fn lambert_w_derivatives_match_finite_differences() {
    for x in [-0.3, -0.1, 0.0, 0.4, 3.0, 100.0] {
        let w = lambert_w0(x);
        let h = 1e-6 * x.abs().max(0.1);
        assert!(
            close(lambert_w_dx(x, w), central(lambert_w0, x, h), 1e-8),
            "{x}"
        );
        let fd = central(|x| lambert_w_dx(x, lambert_w0(x)), x, h);
        assert!(close(lambert_w_dx2(x, w), fd, 1e-6), "{x}");
    }
    for x in [-0.3, -0.1, -1e-3] {
        let w = lambert_wm1(x);
        let h = 1e-6 * x.abs();
        assert!(
            close(lambert_w_dx(x, w), central(lambert_wm1, x, h), 1e-7),
            "{x}"
        );
        let fd = central(|x| lambert_w_dx(x, lambert_wm1(x)), x, h);
        assert!(close(lambert_w_dx2(x, w), fd, 1e-6), "{x}");
    }
}

#[test]
fn hyp2f1_reduces_to_elementary_functions() {
    for z in [-50.0, -2.0, -0.6, -0.1, 0.0, 0.2, 0.5, 0.7, 0.95, 0.999_999] {
        for (a, b) in [(0.7, 2.3), (2.0, 5.5), (-1.5, 0.4)] {
            // ₂F₁(a, b; b; z) = (1 − z)^{−a}
            let (f, expected) = (hyp2f1(a, b, b, z), (1.0 - z).powf(-a));
            assert!(close(f, expected, 1e-13), "{a} {b} {z}: {f} vs {expected}");
        }
        if z != 0.0 {
            // ₂F₁(1, 1; 2; z) = −ln(1 − z)/z
            let (f, expected) = (hyp2f1(1.0, 1.0, 2.0, z), -(-z).ln_1p() / z);
            assert!(close(f, expected, 1e-13), "{z}: {f} vs {expected}");
        }
        if z < 0.0 {
            // ₂F₁(½, 1; 3/2; −t²) = arctan(t)/t
            let t = (-z).sqrt();
            assert!(close(hyp2f1(0.5, 1.0, 1.5, z), t.atan() / t, 1e-13), "{z}");
        }
        // a polynomial: ₂F₁(−2, b; c; z) = 1 − 2bz/c + b(b + 1)z²/(c(c + 1))
        let (b, c) = (1.3, 2.2);
        let p = 1.0 - 2.0 * b * z / c + b * (b + 1.0) * z * z / (c * (c + 1.0));
        assert!(
            (hyp2f1(-2.0, b, c, z) - p).abs() < 1e-13 * p.abs().max(1.0),
            "{z}"
        );
    }
    assert!(hyp2f1(1.0, 1.0, 2.0, 1.0).is_nan());
    assert!(hyp2f1(1.0, 1.0, -2.0, 0.5).is_nan());
    assert!(hyp2f1(1.0, 1.0, 0.0, 0.5).is_nan());
    assert!(hyp2f1(f64::NAN, 1.0, 2.0, 0.5).is_nan());
    assert!(hyp2f1(1.0, 1.0, 2.0, f64::NEG_INFINITY).is_nan());
    assert_eq!(hyp2f1(3.0, 4.0, 5.0, 0.0), 1.0);
}

#[test]
fn hyp2f1_derivatives_match_finite_differences() {
    for &(a, b, c) in &[(0.8, 1.9, 2.7), (2.5, -0.5, 1.5), (4.0, 3.0, 9.0)] {
        for z in [-3.0, -0.4, 0.3, 0.8, 0.97] {
            let d = hyp2f1_derivatives(a, b, c, z);
            assert!(close(d.value, hyp2f1(a, b, c, z), 1e-14));
            assert!(close(d.gradient[3], hyp2f1_dz(a, b, c, z), 1e-12));
            let at = |p: [f64; 4]| hyp2f1(p[0], p[1], p[2], p[3]);
            let gradient_at = |p: [f64; 4]| hyp2f1_derivatives(p[0], p[1], p[2], p[3]).gradient;
            let base = [a, b, c, z];
            for i in 0..4 {
                let h = 1e-6 * base[i].abs().max(0.1) * if i == 3 { 0.1 } else { 1.0 };
                let shifted = |s: f64| {
                    let mut p = base;
                    p[i] += s;
                    p
                };
                let fd = (at(shifted(h)) - at(shifted(-h))) / (2.0 * h);
                assert!(
                    (d.gradient[i] - fd).abs() < 1e-7 * fd.abs().max(d.value.abs()),
                    "{a} {b} {c} {z} ∂{i}: {} vs {fd}",
                    d.gradient[i]
                );
                let (up, down) = (gradient_at(shifted(h)), gradient_at(shifted(-h)));
                for j in 0..4 {
                    let fd = (up[j] - down[j]) / (2.0 * h);
                    assert!(
                        (d.hessian[j][i] - fd).abs() < 1e-6 * fd.abs().max(d.value.abs()),
                        "{a} {b} {c} {z} ∂{i}∂{j}: {} vs {fd}",
                        d.hessian[j][i]
                    );
                    assert_eq!(d.hessian[i][j], d.hessian[j][i]);
                }
            }
        }
    }
    assert!(hyp2f1_derivatives(1.0, 1.0, 2.0, 1.5).gradient[0].is_nan());
}

#[test]
fn owens_t_has_its_special_values_and_symmetries() {
    for h in [0.0, 0.3, 0.67, 1.0, 2.5, 6.0, 12.0] {
        // T(h, 1) = ½Φ(h)(1 − Φ(h))
        let one = 0.5 * ndtr(h) * ndtr(-h);
        assert!(close(owens_t(h, 1.0), one, 1e-14), "{h}");
        // T(h, ∞) = ½(1 − Φ(h))
        assert!(
            close(owens_t(h, f64::INFINITY), 0.5 * ndtr(-h), 1e-14),
            "{h}"
        );
        assert_eq!(owens_t(h, 0.0), 0.0);
        for a in [0.2, 0.8, 1.7, 6.0] {
            let t = owens_t(h, a);
            assert_eq!(owens_t(-h, a), t);
            assert_eq!(owens_t(h, -a), -t);
            // T(h, a) + T(ah, 1/a) = ½Φ(h) + ½Φ(ah) − Φ(h)Φ(ah) for h >= 0
            let sum = t + owens_t(a * h, 1.0 / a);
            let expected = 0.5 * ndtr(h) + 0.5 * ndtr(a * h) - ndtr(h) * ndtr(a * h);
            assert!((sum - expected).abs() < 1e-15, "{h} {a}");
        }
    }
    for a in [0.1, 1.0, 10.0] {
        assert!(close(owens_t(0.0, a), a.atan() / (2.0 * PI), 1e-15));
    }
    assert!(owens_t(f64::NAN, 1.0).is_nan());
    assert_eq!(owens_t(f64::INFINITY, 1.0), 0.0);
    assert_eq!(owens_t(50.0, 0.5), 0.0);
}

#[test]
fn owens_t_derivatives_match_finite_differences() {
    for h in [-1.3, 0.0, 0.4, 1.5, 4.0] {
        for a in [-2.0, 0.3, 1.0, 3.5] {
            let step = 1e-6;
            let fd = central(|h| owens_t(h, a), h, step);
            assert!((owens_t_dh(h, a) - fd).abs() < 1e-9, "{h} {a}");
            let fd = central(|a| owens_t(h, a), a, step);
            assert!((owens_t_da(h, a) - fd).abs() < 1e-9, "{h} {a}");
        }
    }
}
